// Confere o segredo A sobre horario + corpo BRUTO, na mesma janela de 5
// minutos do Atendara. Sem isto, qualquer um que descubra a URL do webhook
// manda mensagem em nome de uma clinica.
const { createHmac, timingSafeEqual } = require('crypto');

const item = $input.first();
const headers = item.json.headers ?? {};
const timestamp = headers['x-atendara-timestamp'] ?? '';
const signature = headers['x-atendara-signature'] ?? '';

// Corpo exatamente como chegou: reserializar mudaria um espaco e derrubaria a
// conferencia.
const raw = item.binary?.data?.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body ?? {});

const expected = createHmac('sha256', $env.ATENDARA_TASK_SECRET).update(`${timestamp}.${raw}`).digest('hex');
const mesmoTamanho = expected.length === String(signature).length;
const assinaturaValida =
  mesmoTamanho && timingSafeEqual(Buffer.from(expected), Buffer.from(String(signature)));
const dentroDaJanela = Math.abs(Date.now() - Date.parse(timestamp)) <= 300000;

const tarefa = JSON.parse(raw);
const vencida = Date.parse(tarefa.expiresAt) <= Date.now();

return [
  {
    json: {
      aceita: assinaturaValida && dentroDaJanela && !vencida,
      motivo: !assinaturaValida ? 'BAD_SIGNATURE' : !dentroDaJanela ? 'STALE_TIMESTAMP' : vencida ? 'TASK_EXPIRED' : 'OK',
      tarefa
    }
  }
];

// Provedor FICTICIO: o resultado e escolhido pelo destino, igual ao provedor
// simulado do Atendara (src/lib/notifications/providers/simulated.ts). Nenhuma
// mensagem sai para ninguem.
const { createHmac } = require('crypto');

const tarefa = $json.tarefa;
const destino = String(tarefa.destination ?? '').toLowerCase();

const FICTICIOS = {
  '+550000000001': { outcome: 'REJECTED', failureCode: 'INVALID_DESTINATION' },
  'recusado@exemplo.invalid': { outcome: 'REJECTED', failureCode: 'INVALID_DESTINATION' },
  '+550000000002': { outcome: 'TEMPORARY_FAILURE', failureCode: 'PROVIDER_UNAVAILABLE' },
  'indisponivel@exemplo.invalid': { outcome: 'TEMPORARY_FAILURE', failureCode: 'PROVIDER_UNAVAILABLE' },
  '+550000000004': { outcome: 'TEMPORARY_FAILURE', failureCode: 'RATE_LIMITED' },
  'limitado@exemplo.invalid': { outcome: 'TEMPORARY_FAILURE', failureCode: 'RATE_LIMITED' }
};

const instavel = destino === '+550000000003' || destino === 'instavel@exemplo.invalid';
const resultado = FICTICIOS[destino]
  ?? (instavel && tarefa.attempt === 1
    ? { outcome: 'TEMPORARY_FAILURE', failureCode: 'PROVIDER_UNAVAILABLE' }
    : { outcome: 'ACCEPTED', failureCode: null });

const corpo = JSON.stringify({
  version: tarefa.version,
  taskId: tarefa.taskId,
  organizationId: tarefa.organizationId,
  attempt: tarefa.attempt,
  outcome: resultado.outcome,
  providerMessageId: resultado.outcome === 'ACCEPTED' ? `n8n_${$execution.id}` : null,
  failureCode: resultado.failureCode
});

// Segredo B, diferente do A: quem recebe tarefas nao consegue forjar
// resultados.
const timestamp = new Date().toISOString();
const assinatura = createHmac('sha256', $env.ATENDARA_CALLBACK_SECRET).update(`${timestamp}.${corpo}`).digest('hex');

return [{ json: { corpo, timestamp, assinatura, url: $env.ATENDARA_CALLBACK_URL } }];
